<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class AcademicControlController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->canDo('students.manage'),403);}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$gid=$r->integer('group')?:$groups->first()?->id;$students=collect();if($gid){$mq=DB::table('student_group_memberships as m')->join('students as s','s.id','=','m.student_id')->where('m.academic_period_id',$p->id)->where('m.study_group_id',$gid)->where('m.status','active');$students=$mq->exists()?$mq->select('s.*')->orderBy('s.last_name')->get():DB::table('students')->where('current_group_id',$gid)->where('status','active')->orderBy('last_name')->get();foreach($students as $s){$res=DB::table('semester_results')->where(['academic_period_id'=>$p->id,'student_id'=>$s->id])->get();$s->debts=$res->filter(fn($x)=>in_array(mb_strtolower((string)$x->value),['2','незачет','незачёт','не зачтено']))->count();$s->results=$res->count();$s->admission=DB::table('attestation_admissions')->where(['academic_period_id'=>$p->id,'student_id'=>$s->id])->whereNull('subject_id')->first();}}return view('academic-office.control',compact('p','groups','gid','students'));}
 public function admission(Request $r,$student){$this->ok($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['status'=>'required|in:admitted,conditional,not_admitted','reason'=>'nullable|string|max:5000']);DB::table('attestation_admissions')->updateOrInsert(['academic_period_id'=>$p->id,'student_id'=>$student,'subject_id'=>null],array_merge($d,['decided_by'=>$r->user()->id,'decided_at'=>now(),'created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Решение о допуске сохранено.');}
}